:root{
--ink:#17232e;
--navy:#101a27;
--cream:#f4f0e5;
--paper:#fbf9f2;
--muted:#8a918e;
--lime:#d4f06b;
--coral:#ff765e;
--teal:#68c9b9;
--line:rgba(23,35,46,.16);
--mono:'DM Mono',monospace;
--display:'Space Grotesk',sans-serif;
--body:'DM Sans',sans-serif}

*{
box-sizing:border-box}
html{
min-height:100%;
background:var(--navy)}
body{
margin:0;
min-height:100vh;
background:var(--cream);
color:var(--ink);
font-family:var(--body);
-webkit-font-smoothing:antialiased}
.app-shell{
max-width:1600px;
min-height:100vh;
margin:0 auto;
background:var(--cream);
overflow:hidden;
position:relative}
.topbar{
height:74px;
padding:0 6.1%;
display:flex;
align-items:center;
justify-content:space-between;
border-bottom:1px solid var(--line);
position:relative;
z-index:4}
.brand{
display:flex;
align-items:center;
gap:11px;
text-decoration:none;
color:var(--ink);
font:700 15px var(--display);
letter-spacing:.11em}
.brand-light{
font-weight:400;
color:#69736f}
.brand-mark{
display:grid;
grid-template-columns:repeat(2,7px);
grid-template-rows:repeat(2,7px);
gap:3px;
transform:rotate(-12deg)}
.brand-mark span{
background:var(--coral);
border-radius:2px}
.brand-mark span:nth-child(2){
background:var(--teal)}
.brand-mark span:nth-child(3){
background:var(--lime)}
.brand-mark span:nth-child(4){
background:var(--ink)}
.top-meta,.sound-toggle{
font:10px var(--mono);
letter-spacing:.08em;
color:#737b77}
.top-meta{
display:flex;
align-items:center;
gap:12px}
.live-dot{
height:7px;
width:7px;
border-radius:50%;
background:#79b4a1;
box-shadow:0 0 0 3px rgba(121,180,161,.16)}
.meta-divider{
height:12px;
border-left:1px solid #c9c8bd}
.sound-toggle{
border:1px solid var(--line);
background:transparent;
padding:9px 12px;
display:flex;
gap:8px;
align-items:center;
color:var(--ink);
cursor:pointer}
.sound-icon{
font-size:15px;
color:#dc765f}
.hidden{
display:none!important}
.welcome-screen{
min-height:calc(100vh - 74px);
padding:75px 10.1% 68px;
display:grid;
grid-template-columns:1fr 1.05fr;
align-items:center;
position:relative}
.welcome-copy{
padding:0 0 10px 0;
z-index:2}
.eyebrow{
font:10px var(--mono);
letter-spacing:.13em;
color:#64706c;
display:flex;
align-items:center;
gap:11px}
.eyebrow-line{
width:24px;
border-top:1px solid var(--coral)}
h1,.chapter-screen-head h2,.complete-card h2{
font:600 clamp(56px,7vw,94px)/.98 var(--display);
letter-spacing:-.075em;
margin:28px 0 22px;
color:var(--ink)}
.italic-word{
font-family:Georgia,serif;
font-weight:400;
font-style:italic;
letter-spacing:-.075em;
color:#e56f57}
.welcome-lede{
font-size:16px;
line-height:1.75;
color:#65706d;
max-width:370px;
margin:0 0 32px}
.welcome-facts{
display:flex;
align-items:center;
gap:24px;
margin:35px 0 37px}
.welcome-facts div{
display:flex;
flex-direction:column;
gap:5px}
.welcome-facts strong{
font:600 19px var(--display);
letter-spacing:-.04em}
.welcome-facts span{
font:9px var(--mono);
letter-spacing:.07em;
color:#8a918e}
.welcome-facts i,.complete-stats i{
height:27px;
border-left:1px solid #cbc9be}
.primary-button{
display:flex;
justify-content:space-between;
align-items:center;
gap:34px;
background:var(--ink);
color:var(--paper);
border:0;
min-width:247px;
padding:17px 19px;
font:10px var(--mono);
letter-spacing:.08em;
cursor:pointer;
transition:background .2s,transform .2s}
.primary-button:hover{
background:#30434a;
transform:translateY(-2px)}
.button-arrow{
font-size:18px;
color:var(--lime)}
.tiny-note{
font:10px var(--mono);
letter-spacing:.02em;
color:#8a918e;
margin-top:18px}
.tiny-note span{
color:#e77b64;
font-size:14px;
margin-right:5px}
.welcome-art{
height:485px;
position:relative;
background:#e8e4d7;
margin-left:12px;
overflow:hidden}

