global.window={};
require('./bank-a.js'); require('./learning-data.js');
console.log(Object.keys(window));
console.log('extra chapters', (window.extraLearningChapters||[]).length);
console.log((window.extraLearningChapters||[]).map(c=>c.id+':'+c.name+':'+c.questions.length).join('\n'));
console.log('bank keys',Object.keys(window.bankA));
console.log('bank counts',Object.entries(window.bankA).map(([k,v])=>k+':'+v.length).join(', '));
console.log('words keys',Object.keys(window.extraChapterWords||{}).length);
"

