243:     oscillator.frequency.value = correct ? 660 : 245;
244:     gain.gain.setValueAtTime(.055, audioContext.currentTime);
245:     gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + .17);
246:     oscillator.connect(gain); gain.connect(audioContext.destination);
247:     oscillator.start(); oscillator.stop(audioContext.currentTime + .18);
248:   } catch (_) { /* Audio is an optional flourish. */ }
249: }
